package org.jsoup.select;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.TokenQueue;
import org.jsoup.select.Evaluator;
import org.jsoup.select.QueryParser;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class QueryParser_parse_TriageGen0Test {

    @Test
    public void testParse_SimpleTag() {
        String query = "div";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
        assertTrue(evaluator.toString().contains("tag(div)"));
    }

    @Test
    public void testParse_IdSelector() {
        String query = "#id";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
        assertTrue(evaluator.toString().contains("id(id)"));
    }

    @Test
    public void testParse_ClassSelector() {
        String query = ".class";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
        assertTrue(evaluator.toString().contains("class(class)"));
    }

    @Test
    public void testParse_AttributeSelector() {
        String query = "[attr=value]";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
        assertTrue(evaluator.toString().contains("attr(attr, value)"));
    }

    @Test
    public void testParse_ComplexSelector() {
        String query = "div.className#id[attr=val]";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
    }

    @Test
    public void testParse_DescendantSelector() {
        String query = "div p";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
    }

    @Test
    public void testParse_ChildSelector() {
        String query = "div > p";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
    }

    @Test
    public void testParse_SiblingSelector() {
        String query = "div + p";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
    }

    @Test
    public void testParse_NextSiblingSelector() {
        String query = "div ~ p";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
    }

    @Test
    public void testParse_PseudoSelector() {
        String query = "div:first-child";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParse_EmptyQuery() {
        // Depending on implementation, empty might throw or return empty evaluator
        // If the parser throws for empty strings, this test is correct.
        QueryParser.parse("");
    }

    @Test(expected = RuntimeException.class)
    public void testParse_InvalidQuery() {
        // Testing for syntax errors that lead to runtime exceptions in the parser
        QueryParser.parse("div[attr");
    }

    @Test
    public void testParse_WhitespaceHandling() {
        String query = "  div   .class  ";
        Evaluator evaluator = QueryParser.parse(query);
        assertNotNull(evaluator);
    }
}
